UPDATE PAYMENT_PROOF
SET REF_NO = #{refNo},
REF_ASSIGNED_AT = #{assignedAt}
WHERE PAYMENT_PROOF_ID = #{proofId}
AND STATUS = 'CONFIRMED'
AND REF_NO IS NULL

UPDATE PAYMENT_PROOF
SET REF_NO = #{newRefNo},
REF_CORRECT_COUNT = REF_CORRECT_COUNT + 1
WHERE PAYMENT_PROOF_ID = #{proofId}
AND REF_NO = #{oldRefNo}

